import{_ as c,C as h,o as t,c as u,a2 as i,b as n,w as a,a as r,E as d,a3 as s,j as l}from"./chunks/framework.BDCokyix.js";const k=JSON.parse('{"title":"Peer Connectivity (Daemon + Bot)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/peer-connectivity.md","filePath":"architecture/peer-connectivity.md","lastUpdated":1780254295000}'),p={name:"architecture/peer-connectivity.md"};function m(b,e,f,v,y,A){const o=h("Mermaid");return t(),u("div",null,[e[2]||(e[2]=i('<h1 id="peer-connectivity-daemon-bot" tabindex="-1">Peer Connectivity (Daemon + Bot) <a class="header-anchor" href="#peer-connectivity-daemon-bot" aria-label="Permalink to &quot;Peer Connectivity (Daemon + Bot)&quot;">​</a></h1><p>This doc describes how Soma peers (the desktop daemon runtime — <code>soma-daemon</code>, embedded in-process in the Tauri host via <code>desktop-daemon</code> — and <code>somad bot</code>) discover each other and establish connectivity using libp2p.</p><p>The implementation lives in the shared peer runtime: <code>backend/crates/peer</code> (<code>soma-peer</code>).</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>Work on LAN without any infrastructure (developer-friendly).</li><li>Work across NAT / different networks with minimal configuration (production-friendly).</li><li>Prefer direct connections, but fall back to relayed connections when necessary.</li></ul><h2 id="user-expectations" tabindex="-1">User Expectations <a class="header-anchor" href="#user-expectations" aria-label="Permalink to &quot;User Expectations&quot;">​</a></h2><ul><li>Content already stored on a device stays usable locally, even on weak networks.</li><li>Peer-dependent actions such as new joins, first-time attachment fetches, and remote updates may wait until another peer is reachable.</li><li>Relay, rendezvous, and cache peers improve reachability. They do not guarantee immediate delivery.</li><li>Reachable is not the same as authorized. A peer may be online but still unable to serve a workspace if membership or cached content is missing.</li></ul><h2 id="mechanisms-in-order-of-what-to-try-first" tabindex="-1">Mechanisms (in order of “what to try first”) <a class="header-anchor" href="#mechanisms-in-order-of-what-to-try-first" aria-label="Permalink to &quot;Mechanisms (in order of “what to try first”)&quot;">​</a></h2><h3 id="_1-direct-dialing-preferred" tabindex="-1">1) Direct dialing (preferred) <a class="header-anchor" href="#_1-direct-dialing-preferred" aria-label="Permalink to &quot;1) Direct dialing (preferred)&quot;">​</a></h3><p>Peers always try to establish <strong>direct connections</strong> using the multiaddrs they learn from discovery (mDNS or rendezvous). Direct connections have the lowest latency and cost.</p><h3 id="_2-identify-connection-metadata" tabindex="-1">2) Identify (connection metadata) <a class="header-anchor" href="#_2-identify-connection-metadata" aria-label="Permalink to &quot;2) Identify (connection metadata)&quot;">​</a></h3><p>Peers run the libp2p <strong>Identify</strong> protocol to exchange:</p><ul><li>supported protocol IDs,</li><li>agent/version strings,</li><li>observed addresses.</li></ul><p>In Soma this is used primarily to improve debug visibility and to help other behaviours infer which addresses are usable.</p><h3 id="_3-mdns-local-network-discovery" tabindex="-1">3) mDNS (local network discovery) <a class="header-anchor" href="#_3-mdns-local-network-discovery" aria-label="Permalink to &quot;3) mDNS (local network discovery)&quot;">​</a></h3><p>When enabled, peers use libp2p mDNS to discover other peers on the same LAN and dial them automatically.</p><ul><li>Enabled by default in <code>soma-peer</code> and can be disabled via <code>--disable-mdns</code>.</li><li>Useful for dev and for “same Wi‑Fi” connectivity.</li></ul><h3 id="_4-rendezvous-internet-discovery" tabindex="-1">4) Rendezvous (internet discovery) <a class="header-anchor" href="#_4-rendezvous-internet-discovery" aria-label="Permalink to &quot;4) Rendezvous (internet discovery)&quot;">​</a></h3><p>Peers can dial one or more rendezvous servers and use the rendezvous <strong>client</strong> protocol to:</p><ul><li>register in a namespace,</li><li>discover other registered peers,</li><li>dial discovered peers.</li></ul><p>Rendezvous is for discovery, not NAT traversal. It helps peers find each other when they are not on the same LAN.</p><h3 id="_5-relay-client-nat-traversal-fallback" tabindex="-1">5) Relay client (NAT traversal fallback) <a class="header-anchor" href="#_5-relay-client-nat-traversal-fallback" aria-label="Permalink to &quot;5) Relay client (NAT traversal fallback)&quot;">​</a></h3><p>Peers can dial one or more relay nodes and use the <strong>relay client</strong> behaviour.</p><p>Common pattern:</p><ul><li>peers proactively connect to configured relays,</li><li>when needed, traffic can be routed through a relay (encrypted end-to-end by libp2p),</li><li>direct connections are still preferred whenever available.</li></ul><p>Note: dialing a relay node without running the relay client behaviour does not provide relayed reachability. Soma peers include the relay client behaviour as part of <code>soma-peer</code>.</p><h2 id="sequence-diagrams" tabindex="-1">Sequence Diagrams <a class="header-anchor" href="#sequence-diagrams" aria-label="Permalink to &quot;Sequence Diagrams&quot;">​</a></h2><h3 id="peer-startup-mdns-rendezvous-relay-configured" tabindex="-1">Peer startup (mDNS + rendezvous + relay configured) <a class="header-anchor" href="#peer-startup-mdns-rendezvous-relay-configured" aria-label="Permalink to &quot;Peer startup (mDNS + rendezvous + relay configured)&quot;">​</a></h3>',28)),(t(),n(s,null,{default:a(()=>[d(o,{id:"mermaid-168",class:"mermaid",graph:"sequenceDiagram%0A%20%20autonumber%0A%20%20participant%20Peer%20as%20Soma%20Peer%20(daemon%2Fbot)%0A%20%20participant%20MDNS%20as%20mDNS%20(LAN)%0A%20%20participant%20RDV%20as%20Rendezvous%20Server%0A%20%20participant%20Relay%20as%20Relay%20Node%0A%20%20participant%20Other%20as%20Another%20Peer%0A%0A%20%20Peer-%3E%3EPeer%3A%20Start%20libp2p%20swarm%20(transports%20%2B%20behaviours)%0A%20%20Peer-%3E%3EPeer%3A%20Listen%20on%20TCP%2FQUIC%2FWS%0A%20%20Peer-%3E%3EPeer%3A%20Identify%20enabled%20(metadata%20exchange)%0A%0A%20%20alt%20mDNS%20enabled%0A%20%20%20%20Peer-%3E%3EMDNS%3A%20Query%20%2F%20announce%20_p2p._udp.local%0A%20%20%20%20MDNS--%3E%3EPeer%3A%20Discovered%20peers%20%2B%20addrs%0A%20%20%20%20Peer-%3E%3EOther%3A%20Dial%20discovered%20addrs%20(direct)%0A%20%20end%0A%0A%20%20opt%20rendezvous%20configured%0A%20%20%20%20Peer-%3E%3ERDV%3A%20Dial%20rendezvous%20multiaddr%0A%20%20%20%20RDV--%3E%3EPeer%3A%20Connection%20established%0A%20%20%20%20Peer-%3E%3ERDV%3A%20Register(namespace%2C%20external%20addrs)%0A%20%20%20%20Peer-%3E%3ERDV%3A%20Discover(namespace)%0A%20%20%20%20RDV--%3E%3EPeer%3A%20Registrations%20(peers%20%2B%20addrs)%0A%20%20%20%20Peer-%3E%3EOther%3A%20Dial%20discovered%20addrs%20(direct)%0A%20%20end%0A%0A%20%20opt%20relay%20configured%0A%20%20%20%20Peer-%3E%3ERelay%3A%20Dial%20relay%20multiaddr%0A%20%20%20%20Relay--%3E%3EPeer%3A%20Connection%20established%0A%20%20%20%20Peer-%3E%3ERelay%3A%20Relay%20client%20active%20(reservation%20%2F%20relayed%20reachability)%0A%20%20end%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l("h3",{id:"direct-first-dialing-with-relay-fallback-conceptual",tabindex:"-1"},[r("Direct-first dialing with relay fallback (conceptual) "),l("a",{class:"header-anchor",href:"#direct-first-dialing-with-relay-fallback-conceptual","aria-label":'Permalink to "Direct-first dialing with relay fallback (conceptual)"'},"​")],-1)),(t(),n(s,null,{default:a(()=>[d(o,{id:"mermaid-172",class:"mermaid",graph:"sequenceDiagram%0A%20%20autonumber%0A%20%20participant%20A%20as%20Peer%20A%0A%20%20participant%20B%20as%20Peer%20B%0A%20%20participant%20RDV%20as%20Rendezvous%20Server%0A%20%20participant%20Relay%20as%20Relay%20Node%0A%0A%20%20A-%3E%3ERDV%3A%20Discover(namespace)%0A%20%20RDV--%3E%3EA%3A%20B's%20addresses%20(direct%20%2B%20maybe%20relayed)%0A%20%20A-%3E%3EB%3A%20Dial%20direct%20address%0A%20%20alt%20direct%20succeeds%0A%20%20%20%20B--%3E%3EA%3A%20Connection%20established%20(direct)%0A%20%20%20%20A-%3E%3EB%3A%20Identify%20%2B%20app%20protocols%0A%20%20else%20direct%20fails%0A%20%20%20%20A-%3E%3ERelay%3A%20Dial%20relay%20(if%20not%20already%20connected)%0A%20%20%20%20A-%3E%3EB%3A%20Dial%20relayed%20address%20via%20relay%0A%20%20%20%20B--%3E%3EA%3A%20Connection%20established%20(relayed)%0A%20%20%20%20A-%3E%3EB%3A%20Identify%20%2B%20app%20protocols%0A%20%20end%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i('<h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="desktop-daemon-embedded-in-the-tauri-host" tabindex="-1">Desktop daemon (embedded in the Tauri host) <a class="header-anchor" href="#desktop-daemon-embedded-in-the-tauri-host" aria-label="Permalink to &quot;Desktop daemon (embedded in the Tauri host)&quot;">​</a></h3><p>The desktop daemon library reads its connectivity configuration from the runtime config the Tauri host&#39;s <code>desktop-daemon</code> crate constructs at startup. The relevant fields:</p><ul><li><code>listenAddrs</code> (array of multiaddrs)</li><li><code>bootstrapAddrs</code></li><li><code>rendezvousAddrs</code></li><li><code>relayAddrs</code></li><li><code>enableMdns</code></li></ul><p>There are no CLI flags or <code>SOMA_*</code> environment variables on the desktop side — the host process constructs the config directly when it spins up the embedded runtime.</p><h3 id="somad-bot-server-peer" tabindex="-1"><code>somad bot</code> (server peer) <a class="header-anchor" href="#somad-bot-server-peer" aria-label="Permalink to &quot;`somad bot` (server peer)&quot;">​</a></h3><ul><li><code>--listen-addrs</code> / <code>SOMA_LISTEN_ADDRS</code> (comma-delimited)</li><li><code>--bootstrap-addrs</code> / <code>SOMA_BOOTSTRAP_ADDRS</code> (comma-delimited)</li><li><code>--rendezvous-addrs</code> / <code>SOMA_RDV_ADDRS</code> (comma-delimited)</li><li><code>--relay-addrs</code> / <code>SOMA_RELAY_ADDRS</code> (comma-delimited)</li><li><code>--disable-mdns</code> / <code>SOMA_DISABLE_MDNS</code></li></ul><h2 id="local-development-recipes" tabindex="-1">Local Development Recipes <a class="header-anchor" href="#local-development-recipes" aria-label="Permalink to &quot;Local Development Recipes&quot;">​</a></h2><h3 id="start-infra" tabindex="-1">Start infra <a class="header-anchor" href="#start-infra" aria-label="Permalink to &quot;Start infra&quot;">​</a></h3><p>From the repo root:</p><ul><li>Relay: <code>just backend-run-relay</code></li><li>Rendezvous: <code>just backend-run-rendezvous</code></li></ul><p>Copy their logged listen multiaddrs (including <code>/p2p/&lt;peerid&gt;</code>).</p><h3 id="run-the-desktop-app-and-point-it-at-infra" tabindex="-1">Run the desktop app and point it at infra <a class="header-anchor" href="#run-the-desktop-app-and-point-it-at-infra" aria-label="Permalink to &quot;Run the desktop app and point it at infra&quot;">​</a></h3><p>The Tauri app embeds the daemon runtime, so connectivity is configured by the host&#39;s <code>desktop-daemon</code> crate when it constructs the runtime config at startup. Adjust that config (or the desktop stage config it reads) to inject your local <code>--rendezvous-addrs</code> / <code>--relay-addrs</code> equivalents.</p><h3 id="observe-behaviour" tabindex="-1">Observe behaviour <a class="header-anchor" href="#observe-behaviour" aria-label="Permalink to &quot;Observe behaviour&quot;">​</a></h3><p>In logs you should see:</p><ul><li>connection establishment / errors,</li><li>identify events,</li><li>rendezvous discoveries,</li><li>relay reservation acceptance / relayed circuits (when used).</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="a-join-request-does-not-complete" tabindex="-1">A join request does not complete <a class="header-anchor" href="#a-join-request-does-not-complete" aria-label="Permalink to &quot;A join request does not complete&quot;">​</a></h3><ul><li>Confirm the requester has the correct approver peer ID and reachable connection addresses.</li><li>Confirm the approver is actually authorized to approve for that space.</li><li>Remember that a submitted request does not make the requester a member yet.</li><li>If either peer is offline, approval delivery may be queued until connectivity returns.</li></ul><h3 id="an-attachment-does-not-open-on-this-device" tabindex="-1">An attachment does not open on this device <a class="header-anchor" href="#an-attachment-does-not-open-on-this-device" aria-label="Permalink to &quot;An attachment does not open on this device&quot;">​</a></h3><ul><li>If the attachment was already fetched locally, it should still open without another peer.</li><li>If this is the first fetch, the daemon may still need a reachable authorized peer or cache peer that already has the blob.</li><li>Relay and rendezvous help peers find each other, but they do not store uncached attachment bytes.</li></ul><h3 id="a-peer-looks-reachable-but-content-still-does-not-arrive" tabindex="-1">A peer looks reachable, but content still does not arrive <a class="header-anchor" href="#a-peer-looks-reachable-but-content-still-does-not-arrive" aria-label="Permalink to &quot;A peer looks reachable, but content still does not arrive&quot;">​</a></h3><ul><li>Discovery is not the same as successful content delivery.</li><li>Check whether the device is actually a member of the space before assuming blob or document access should work.</li><li>Inspect daemon and bot logs for join failures, blob read failures, or missing membership state.</li></ul>',24))])}const P=c(p,[["render",m]]);export{k as __pageData,P as default};
